      A · 今日目录推荐。把信息空间几乎全部给标题和顺序，最接近“十秒内知道今天有什么”。首屏的编辑判断受限于三条“先看”目录自身完成主要浏览任务最适合保留为默认首页方向
      B · 头版 + 全览为当天留一个克制的头版锚点，再迅速让位给目录。编辑感最完整一篇内容优先级更高比 A 多一点情绪与停留
      C · 主题分版先让读者按主题扫读，再回到完整目录避免遗漏。发现路径更强依赖稳定的分类质量适合作为兴趣功能成熟后的方向




    const body = document.body;
    const themeButton = document.querySelector('#theme-toggle');
    const viewButtons = [...document.querySelectorAll('[data-view]')];
    const layouts = [...document.querySelectorAll('[data-layout]')];
    const notes = [...document.querySelectorAll('[data-note]')];

    function setTheme(theme) {
      const isNight = theme === 'night';
      body.dataset.theme = isNight ? 'night' : 'day';
      themeButton.setAttribute('aria-pressed', String(isNight));
      themeButton.textContent = isNight ? '切换暖纸日间' : '切换夜间墨纸';
      localStorage.setItem('dailyreader-prototype-theme', body.dataset.theme);
    }

    function setLayout(layout) {
      const selectedLayout = viewButtons.some((button) => button.dataset.view === layout) ? layout : 'directory';
      viewButtons.forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.view === selectedLayout)));
      layouts.forEach((section) => section.classList.toggle('is-active', section.dataset.layout === selectedLayout));
      notes.forEach((note) => { note.hidden = note.dataset.note !== selectedLayout; });
      localStorage.setItem('dailyreader-prototype-layout', selectedLayout);
    }

    themeButton.addEventListener('click', () => setTheme(body.dataset.theme === 'night' ? 'day' : 'night'));
    viewButtons.forEach((button) => button.addEventListener('click', () => setLayout(button.dataset.view)));

    setTheme(localStorage.getItem('dailyreader-prototype-theme') || 'day');
    setLayout(localStorage.getItem('dailyreader-prototype-layout') || 'directory');
